import { setTimeout } from "./timers"

/**
 * Forces a chunk to be loaded.
 * @param x - The x coordinate of the chunk
 * @param y - The y coordinate of the chunk
 * @param z - The z coordinate of the chunk
 * @param onLoaded - The function to call when the chunk is loaded
 */
export function forceLoadChunk(x: number, y: number, z: number, onLoaded: () => void) {
	const block = api.getBlock(x, y, z)
	if (block !== "Unloaded") {
		onLoaded()
		return
	}

	setTimeout(() => {
		forceLoadChunk(x, y, z, onLoaded)
	}, 100)
}
